const $=id=>document.getElementById(id);
const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const lvd=()=>{const u=S.me;if(!u||u.role!="client"||!u.lv)return 0;const l=S.levels.find(x=>x.id==u.lv);return l?l.d:0};
const pr=i=>Math.round(i.p*(100-Math.min(100,(i.d||0)+lvd()))/100);
