function vHome(a){a.innerHTML=`${railHome()}<div class="card hero">${S.shop.logo?`<img src="${S.shop.logo}" style="height:80px"><br>`:""}<h2>${esc(S.shop.name)}</h2><p class="mu">${esc(S.shop.addr)} · ${esc(S.shop.tel)}<br>${esc(S.shop.hours)}</p>${S.shop.promo?`<p><span class="tag" style="font-size:1rem;padding:6px 12px">🎉 ${esc(S.shop.promo)}</span></p>`:""}<button class="btn p" onclick="go(S.me?'book':'register')">Agenda tu cita</button> <button class="btn" onclick="go('login')">Ya tengo cuenta</button><p class="mu">Acumula ${S.loy.need} puntos y canjéalos por un servicio gratis.</p></div>
<div class="card"><h2>Servicios</h2><div class="grid">${S.services.map(s=>`<div class="card"><b>${esc(s.n)}</b><br><span class="mu">${s.m} min</span><br>${price(s)}${s.pk>0?` <span class="mu">Niño $${s.pk}</span>`:""}</div>`).join("")}</div></div>
<div class="card"><h2>Productos</h2><div class="grid">${S.products.map(p=>`<div class="card"><b>${esc(p.n)}</b><br>${price(p)}</div>`).join("")}</div><p class="mu">Agrégalos al agendar tu cita y recógelos en el local.</p></div>${promoHome()}${homeExtra()}${socHome()}${mapHome()}`;startRail()}
function vLogin(a){a.innerHTML=`<div class="card"><h2>Iniciar sesión</h2><label>Usuario o correo</label><input id="e"><label>Contraseña</label><input id="p" type="password"><br><br><button class="btn p" onclick="doLogin()">Entrar</button><p class="mu">Clientes: correo. Empleados y admin: nombre de usuario.<br>Demo admin: admin / admin123</p></div>`}
function doLogin(){const v=$("e").value.trim().toLowerCase();const u=v&&S.users.find(x=>(x.user||"").toLowerCase()==v||(x.email||"").toLowerCase()==v);
if(!u||u.pass!=$("p").value)return toast("Datos incorrectos");S.me=u;save();go(u.role=="admin"?"admin":u.role=="staff"?"staff":"book")}
function vReg(a){a.innerHTML=`<div class="card"><h2>Crear cuenta</h2><label>Nombre</label><input id="n"><label>Teléfono</label><input id="t" type="tel"><label>Correo</label><input id="e" type="email"><label>Contraseña</label><input id="p" type="password"><br><br><button class="btn p" onclick="doReg()">Registrarme</button></div>`}
function doReg(){const e=$("e").value.trim(),n=$("n").value.trim();if(!e||!n||!$("p").value)return toast("Completa los datos");
if(S.users.some(x=>(x.email||"").toLowerCase()==e.toLowerCase()||(x.user||"").toLowerCase()==e.toLowerCase()))return toast("Ese correo ya existe");
const u={email:e,pass:$("p").value,name:n,tel:$("t").value,role:"client",pts:0};S.users.push(u);S.me=u;save();toast("Cuenta creada");go("book")}
function vBook(a){if(!S.me||S.me.role!="client")return go(S.me?"admin":"login");const can=(S.me.pts||0)>=S.loy.need;
a.innerHTML=`${agendaCard(S.appts.filter(x=>x.email==S.me.email))}<div class="card"><h2>Agendar cita</h2><p class="mu">Tus puntos: <b>${S.me.pts||0}</b> (${S.loy.need} = servicio gratis)</p>
<label>Servicio</label><select id="sv" onchange="refSlots()">${S.services.map(s=>`<option value="${s.id}">${esc(s.n)} - $${pr(s)}</option>`).join("")}</select>
<label>Empleado o estación</label><select id="sf" onchange="refSlots()"><option value="0">Sin preferencia</option>${S.staff.map(s=>`<option value="${s.id}">${esc(s.n)} (Estación ${s.st})${s.bio?" - "+esc(s.bio):""}</option>`).join("")}</select>
<div class="grid" style="grid-template-columns:1fr"><div><label>Fecha</label><div id="cal"></div><input id="d" type="hidden"></div><div><label>Hora disponible</label><div id="tm" class="row"></div><input id="h" type="hidden"></div></div>
<label>¿Para quién es la cita?</label><select id="who" onchange="whoCh()"><option value="me">Para mí</option><option value="other">Para otra persona</option></select><div id="ot" class="hidden"><div class="grid"><div><label>Nombre de la persona</label><input id="on"></div><div><label>¿Es niño o adulto?</label><select id="ok" onchange="refSlots()"><option>Adulto</option><option>Niño</option></select></div></div></div><label>Acompañantes (solo lo acompañan, no reciben servicio)</label><div id="cp"></div><button class="btn" type="button" onclick="addComp()">+ Agregar acompañante</button><label>Productos para recoger en tu cita (opcional)</label>${S.products.filter(p=>p.s>0).map(p=>`<div class="row"><span style="flex:1">${esc(p.n)} ${price(p)} <span class="mu">(${p.s} pz)</span></span><input id="q${p.id}" type="number" min="0" max="${p.s}" value="0" style="width:80px"></div>`).join("")||'<p class="mu">Sin productos disponibles.</p>'}
${can?`<label class="row"><input id="fr" type="checkbox" style="width:auto" onchange="refSlots()"> Canjear ${S.loy.need} puntos por servicio gratis</label>`:""}
<label>Forma de pago</label><select id="pm"><option value="efectivo">Efectivo en el local</option><option value="linea">Pago en línea (tarjeta)</option></select><p id="tot" class="mu"></p><button class="btn p" onclick="doBook()">Confirmar cita</button></div>`;drawComp();refSlots()}
function doBook(){const d=$("d").value,h=$("h").value;if(!d||!h)return toast("Elige fecha y hora");const sf=+$("sf").value;
if(!slots(d,sf,bookDur(),0,+$("sv").value).includes(h))return toast("Ese horario ya no está disponible");
const sv=S.services.find(x=>x.id==$("sv").value),items=[];
for(const p of S.products){const el=$("q"+p.id),q=el?parseInt(el.value)||0:0;if(q>p.s)return toast("No hay suficientes piezas de "+p.n);if(q>0)items.push({id:p.id,n:p.n,q,p:pr(p),c:p.cost||0})}
const free=!!($("fr")&&$("fr").checked);const oth=$("who").value=="other"?{n:$("on").value.trim(),t:$("ok").value}:null;if(oth&&!oth.n)return toast("Escribe el nombre de la otra persona");const cs=comp.filter(c=>c.s).map(c=>{const z=S.services.find(x=>x.id==c.s);return{n:z.n,t:c.t,w:c.n,p:prK(z,c.t),m:z.m}});items.forEach(i=>prod(i.id).s-=i.q);if(free)S.me.pts-=S.loy.need;
S.appts.push({id:Date.now(),client:S.me.name,email:S.me.email,service:sv.n,sp:(free?0:prK(sv,oth?oth.t:"Adulto"))+cs.reduce((s,c)=>s+c.p,0),free,staff:sf,date:d,time:h,m:bookDur(),cs,for:oth,comp:comp.slice(),pay:$("pm").value,status:"pendiente",items});
S.notifs.push({t:apptMsg(S.appts[S.appts.length-1],"Nueva cita"),read:false,staff:sf});comp=[];save();toast("Cita agendada");go("mine")}
function vMine(a){if(!S.me||S.me.role!="client")return go(S.me?"admin":"login");const l=S.appts.filter(x=>x.email==S.me.email);
a.innerHTML=`${agendaCard(l)}<div class="card"><h2>Mis citas · ${S.me.pts||0} puntos</h2>${l.length?`<div class="scroll"><table><tr><th>Fecha</th><th>Servicio</th><th>Productos a recoger</th><th>Atiende</th><th>Total</th><th>Estado</th></tr>${l.map(x=>`<tr><td>${x.date} ${x.time}</td><td>${esc(x.service)}${x.free?" (gratis)":""}<div class="mu">${esc(whoTxt(x))}</div></td><td>${itemsTxt(x)}</td><td>${esc(staffName(x.staff))}</td><td>$${x.sp+x.items.reduce((s,t)=>s+t.p*t.q,0)} (${x.pay=="linea"?"línea":"efectivo"})</td><td>${x.status}${x.status=="completada"&&!x.rv?` <button onclick="rate(${x.id})">Dejar reseña</button>`:""}</td></tr>`).join("")}</table></div>`:'<p class="mu">Aún no tienes citas.</p>'}</div>${rvForm()}`}
function vStaff(a){if(!S.me||S.me.role!="staff")return go("login");const l=S.appts.filter(x=>(P("allCitas")||x.staff==S.me.staffId)&&x.status!="cancelada");
a.innerHTML=`${staffExtra()}<div class="card"><h2>Mi agenda</h2>${l.length?`<table><tr><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Productos</th><th>Cobro</th></tr>${l.map(x=>`<tr><td>${x.date} ${x.time}</td><td>${esc(x.client)}<div class="mu">${esc(whoTxt(x))}</div></td><td>${esc(x.service)}</td><td>${itemsTxt(x)}</td><td>${saleCell(x)}</td></tr>`).join("")}</table>`:'<p class="mu">No tienes citas asignadas.</p>'}</div>`}
// ---- Punto de venta en el local ----
const svc=id=>S.services.find(x=>x.id==id);let sk=[];const tkTotal=()=>tk.reduce((s,t)=>s+pr(prod(t.id))*t.q,0)+sk.reduce((s,id)=>s+pr(svc(id)),0);
function vPos(a){if(!S.me||S.me.role=="client"||(S.me.role=="staff"&&!P("pos")))return go("login");const today=ymd(new Date()),ts=S.sales.filter(x=>x.seller&&x.iso==today&&(S.me.role=="admin"||x.seller==S.me.name));
a.innerHTML=`<div class="card"><h2>Productos en el local</h2><div class="grid">${S.products.map(p=>`<div class="card"><b>${esc(p.n)}</b><br>${price(p)}<br><span class="mu">${p.s>0?p.s+" pz en stock":"Agotado"}</span>${p.s>0&&p.s<=3?' <span class="tag" style="background:#c0392b">Pocas piezas</span>':""}<br><br><button ${p.s>0?"":"disabled"} onclick="tkAdd(${p.id})">Agregar al ticket</button></div>`).join("")}</div>${S.me.role=="admin"?'<p class="mu">Para surtir piezas o cambiar precios: Panel admin > Productos.</p>':""}</div>
<div class="card"><h2>Escanear código o agregar servicio</h2><div class="grid"><div><label>Código de barras (Enter)</label><input id="bc" onkeydown="if(event.key=='Enter')scan(this.value)"></div><div><label>Agregar servicio al ticket</label><select onchange="svAdd(this.value)"><option value="">Elegir...</option>${S.services.map(s=>`<option value="${s.id}">${esc(s.n)} $${pr(s)}</option>`).join("")}</select></div></div></div><div class="card"><h2>Ticket de venta</h2>${tk.length||sk.length?`<table>${sk.map((id,i)=>`<tr><td>${esc(svc(id).n)}</td><td><button onclick="sk.splice(${i},1);render()">Quitar</button></td><td>$${pr(svc(id))}</td></tr>`).join("")}${tk.map(t=>{const p=prod(t.id);return`<tr><td>${esc(p.n)}</td><td><button onclick="tkMinus(${t.id})">−</button> ${t.q} <button onclick="tkAdd(${t.id})">+</button></td><td>$${pr(p)*t.q}</td></tr>`}).join("")}</table><p><b>Total: $${tkTotal()}</b></p>`:'<p class="mu">Agrega productos al ticket.</p>'}
<div class="grid"><div><label>Forma de pago</label><select id="pp"><option value="efectivo">Efectivo</option><option value="tarjeta">Tarjeta (terminal del local)</option></select></div><div><label>Propina $</label><input id="tp" type="number" min="0"></div><div><label>Efectivo recibido (opcional)</label><input id="rc" type="number" min="0"></div></div><br><button class="btn p" onclick="cobrar()">Cobrar</button></div>
${S.last?`<div class="card"><h2>Último ticket</h2><pre class="mu" style="white-space:pre-wrap">${esc(S.last)}</pre><a href="https://wa.me/?text=${encodeURIComponent(S.last)}" target="_blank" rel="noopener">Enviar por WhatsApp</a> · <button onclick="window.print()">Imprimir</button></div>`:""}<div class="card"><h2>Ventas de hoy: $${ts.reduce((s,x)=>s+x.amt,0)} (${ts.length})</h2>${S.sales.filter(x=>x.seller&&(S.me.role=="admin"||x.seller==S.me.name)).slice(-8).reverse().map(x=>`<div class="mu">${esc(x.date)} · ${esc(x.items.map(i=>i.q+" x "+i.n).join(", "))} — $${x.amt} (${x.pay}) · ${esc(x.seller)}</div>`).join("")||'<span class="mu">Aún no hay ventas.</span>'}</div>${S.me.role=="staff"&&P("corte")?tCorte():""}${S.me.role=="staff"&&P("inv")?tProd():""}`}
function tkAdd(id){const p=prod(id),t=tk.find(x=>x.id==id);if((t?t.q:0)+1>p.s)return toast("No hay más piezas en stock");t?t.q++:tk.push({id,q:1});render()}
function tkMinus(id){const t=tk.find(x=>x.id==id);if(!t)return;t.q--;if(t.q<=0)tk=tk.filter(x=>x.id!=id);render()}
function cobrar(){if(!tk.length&&!sk.length)return toast("El ticket está vacío");const pay=$("pp").value,tot=tkTotal(),tip=+($("tp").value||0),rc=+($("rc").value||0);
for(const t of tk)if(t.q>prod(t.id).s)return toast("Stock insuficiente de "+prod(t.id).n);
if(pay=="efectivo"&&rc&&rc<tot+tip)return toast("El efectivo recibido no alcanza");
const items=tk.map(t=>{const p=prod(t.id);p.s-=t.q;return{n:p.n,q:t.q,p:pr(p),c:p.cost||0}});
const iso=ymd(new Date()),dt=new Date().toLocaleString("es-MX"),sid=S.me.staffId||0,sv=sk.map(id=>({n:svc(id).n,q:1,p:pr(svc(id)),c:0}));
if(items.length)S.sales.push({date:dt,iso,type:"producto",amt:items.reduce((s,i)=>s+i.p*i.q,0),cost:items.reduce((s,i)=>s+i.c*i.q,0),seller:S.me.name,sid,items,pay,tip});
if(sv.length)S.sales.push({date:dt,iso,type:"corte",amt:sv.reduce((s,i)=>s+i.p,0),cost:0,seller:S.me.name,sid,items:sv,pay,tip:items.length?0:tip});
S.last=`Ticket ${S.shop.name}\n${dt}\n`+items.concat(sv).map(i=>i.q+" x "+i.n+" $"+i.p*i.q).join("\n")+`\nPropina: $${tip}\nTotal: $${tot+tip} (${pay})\nGracias por tu visita`;
tk=[];sk=[];save();toast(pay=="efectivo"&&rc?"Venta lista. Cambio: $"+(rc-tot-tip):"Venta registrada: $"+(tot+tip));render()}
// ---- Panel admin ----
const TABS={citas:"Citas",personal:"Empleados y configuración",precios:"Precios y promos",productos:"Productos",graficas:"Gráficas",lealtad:"Puntos y niveles",diseno:"Colores y datos",gastos:"Gastos",corte:"Corte de caja",agenda:"Agenda",galeria:"Galería",inicio:"Inicio y diseño",mia:"Mi perfil de empleado"};
function vAdmin(a){if(!S.me||S.me.role!="admin")return go("login");const un=S.notifs.filter(n=>!n.read);
a.innerHTML=`<div class="card"><h2>Notificaciones (${un.length})</h2>${S.notifs.slice(-4).reverse().map(n=>`<div class="mu">${n.read?"":"● "}${esc(n.t)} ${sendLinks(n.t)}</div>`).join("")||'<span class="mu">Sin notificaciones</span>'}<br><button onclick="S.notifs.forEach(n=>n.read=true);save();render()">Marcar leídas</button></div>
<div class="tabs">${Object.keys(TABS).map(k=>`<button class="${k==tab?"on":""}" onclick="tab='${k}';render()">${TABS[k]}</button>`).join("")}</div>${({citas:tCitas,personal:tStaff,precios:tPrecios,productos:tProd,graficas:tGraf,lealtad:tLoy,diseno:tDis,gastos:()=>expView(true),corte:tCorte,agenda:tAgenda,galeria:tGal,inicio:tDesign,mia:tMia})[tab]()}`}
function tCitas(){return`<div class="card"><h2>Citas</h2>${S.appts.length?`<div class="scroll"><table><tr><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Productos</th><th>Duración (min)</th><th>Asignar a</th><th>Pago</th><th>Estado</th></tr>${S.appts.map((x,i)=>`<tr><td><input type="date" value="${x.date}" style="width:auto" onchange="resch(${i},'date',this.value)"><input type="time" value="${x.time}" style="width:auto" onchange="resch(${i},'time',this.value)"></td><td>${esc(x.client)}<div class="mu">${esc(whoTxt(x))}</div></td><td>${esc(x.service)}${x.free?" (gratis)":""}</td><td>${itemsTxt(x)}</td><td><input type="number" min="5" step="5" value="${x.m||30}" style="width:80px" onchange="setDur(${i},this.value)">${outWin(x)?'<div class="tag" style="background:#c0392b">Fuera de horario</div>':""}</td><td><select onchange="assignA(${i},this.value)">${staffOpts(x.staff)}</select></td><td>${x.pay=="linea"?"Línea":"Efectivo"}</td><td><select onchange="setSt(${i},this.value)">${["pendiente","confirmada","completada","cancelada"].map(s=>`<option${s==x.status?" selected":""}>${s}</option>`).join("")}</select></td></tr>`).join("")}</table></div><p class="mu">Al marcar "completada" se registra la venta (gráficas) y se suman puntos. Al cancelar se devuelven piezas y puntos.</p>`:'<p class="mu">Sin citas todavía.</p>'}</div>`}
function setSt(i,v){const x=S.appts[i];if(x.done||x.status=="cancelada"){toast("Esa cita ya está cerrada");return render()}
const u=S.users.find(c=>c.email==x.email);
if(v=="cancelada"){x.items.forEach(t=>{const p=prod(t.id);if(p)p.s+=t.q});if(x.free&&u)u.pts+=S.loy.need}
if(v=="completada"){x.done=true;if(x.sp>0||x.tip)S.sales.push({iso:x.date,type:"corte",amt:x.sp,n:x.service,pay:x.pay,sid:x.staff,tip:x.tip||0,cost:0});const pt=x.items.reduce((s,t)=>s+t.p*t.q,0);if(pt>0)S.sales.push({iso:x.date,type:"producto",amt:pt,n:"Cita",pay:x.pay,sid:x.staff,cost:x.items.reduce((s,t)=>s+(t.c||0)*t.q,0)});if(!x.free&&u)u.pts=(u.pts||0)+S.loy.per}
x.status=v;if(v=="completada")S.notifs.push({t:apptMsg(x,"Cita completada"),read:false,staff:x.staff});save();toast("Cita "+v);render()}
function tStaff(){return`<div class="card"><h2>Perfil de empleados</h2>${S.staff.map(s=>`<div class="card"><div class="grid"><div><label>Nombre</label><input value="${esc(s.n)}" onchange="stf(${s.id},'n',this.value)"></div><div><label>Estación #</label><input type="number" value="${s.st}" onchange="stf(${s.id},'st',this.value)"></div><div><label>Teléfono</label><input value="${esc(s.tel)}" onchange="stf(${s.id},'tel',this.value)"></div><div><label>Especialidad / descripción</label><input value="${esc(s.bio)}" onchange="stf(${s.id},'bio',this.value)"></div><div><label>Entrada (vacío = horario general)</label><input type="time" value="${s.so||""}" onchange="stf(${s.id},'so',this.value)"></div><div><label>Salida</label><input type="time" value="${s.sc||""}" onchange="stf(${s.id},'sc',this.value)"></div></div>${permsRow(s.id)}</div>`).join("")}</div>
<div class="card"><h2>Nuevo empleado</h2><div class="grid"><div><label>Nombre</label><input id="sn"></div><div><label>Estación #</label><input id="ss" type="number"></div><div><label>Usuario (opcional, se puede asignar después)</label><input id="su"></div><div><label>Contraseña</label><input id="sp"></div></div><br><button class="btn p" onclick="addStaff()">Agregar empleado</button></div>`}
function stf(id,k,v){const s=S.staff.find(x=>x.id==id);s[k]=k=="st"?+v:v;if(k=="n"){const u=S.users.find(x=>x.staffId==id);if(u)u.name=v}if(k=="so"||k=="sc"){const n=S.appts.filter(x=>x.staff==id&&x.status!="cancelada"&&x.date>=ymd(new Date())&&outWin(x)).length;if(n)S.notifs.push({t:"Cambió el horario de "+s.n+": "+n+" cita(s) quedaron fuera de su horario. Revísalas en Citas.",read:false})}save();toast("Guardado");if(k=="so"||k=="sc")render()}
function addStaffOld(){const n=$("sn").value.trim(),u=$("su").value.trim();if(!n||!u||!$("sp").value)return toast("Completa los datos");
if(S.users.some(x=>(x.user||x.email||"").toLowerCase()==u.toLowerCase()))return toast("Ese usuario ya existe");
const id=Date.now();S.staff.push({id,n,st:+$("ss").value||S.staff.length+1,tel:"",bio:""});S.users.push({user:u,pass:$("sp").value,name:n,role:"staff",staffId:id});save();toast("Empleado agregado");render()}
function ed(l,id,k,v){const o=S[l].find(x=>x.id==id),old=o[k];o[k]=k=="n"||k=="c"?v:Math.max(0,k=="d"?Math.min(100,+v||0):+v||0);if(l=="services"&&k=="m")svMin(o,o[k]-(old||0));save();toast("Guardado")}
const numIn=(l,o,k)=>`<td><input type="number" min="0" value="${o[k]||0}" onchange="ed('${l}',${o.id},'${k}',this.value)"></td>`;
function tPrecios(){return`<div class="card"><h2>Promoción en la página de inicio</h2><input id="pm" value="${esc(S.shop.promo)}" placeholder="Ej: 2x1 en barba los martes"><br><br><button class="btn p" onclick="S.shop.promo=$('pm').value;save();toast('Guardado')">Guardar promoción</button></div>
<div class="card"><h2>Precios de cortes y servicios</h2><div class="scroll"><table><tr><th>Servicio</th><th>Precio $</th><th>Min</th><th>Descuento %</th><th>Precio niño $ (0 = igual)</th></tr>${S.services.map(s=>`<tr><td>${esc(s.n)}</td>${numIn("services",s,"p")}${numIn("services",s,"m")}${numIn("services",s,"d")}${numIn("services",s,"pk")}</tr>`).join("")}</table></div>
<h2 style="margin-top:14px">Nuevo servicio</h2><div class="grid"><div><label>Nombre</label><input id="vn"></div><div><label>Precio $</label><input id="vp" type="number"></div><div><label>Minutos</label><input id="vm" type="number"></div></div><br><button class="btn p" onclick="addSv()">Agregar servicio</button></div>`}
function addSv(){const n=$("vn").value.trim();if(!n)return toast("Escribe el nombre");S.services.push({id:Date.now(),n,p:+$("vp").value||0,m:+$("vm").value||30,d:0});save();render()}
function tProd(){const lw=S.products.filter(p=>p.s<=(p.min||3)),oc="Orden de compra "+S.shop.name+":\n"+lw.map(p=>"- "+p.n+": pedir "+Math.max(1,(p.min||3)*2-p.s)+" pz").join("\n");return`${lw.length?`<div class="card"><h2>⚠ Inventario bajo</h2>${lw.map(p=>`<div class="mu">${esc(p.n)}: ${p.s} pz</div>`).join("")}${S.shop.prov?`<a href="${waTo(S.shop.prov,oc)}" target="_blank" rel="noopener">Enviar orden de compra al proveedor</a>`:'<span class="mu">Agrega el WhatsApp del proveedor en Colores y datos.</span>'}</div>`:""}<div class="card"><h2>Productos, precios y piezas</h2><div class="scroll"><table><tr><th>Producto</th><th>Precio $</th><th>Piezas</th><th>Descuento %</th><th>Costo $</th><th>Mín.</th><th>Código</th><th></th></tr>${S.products.map(p=>`<tr><td>${esc(p.n)}</td>${numIn("products",p,"p")}${numIn("products",p,"s")}${numIn("products",p,"d")}${numIn("products",p,"cost")}<td><input type="number" min="0" value="${p.min||3}" onchange="ed('products',${p.id},'min',this.value)"></td><td><input value="${esc(p.c||"")}" onchange="ed('products',${p.id},'c',this.value)"></td><td><button onclick="delP(${p.id})">Quitar</button></td></tr>`).join("")}</table></div>
<h2 style="margin-top:14px">Nuevo producto</h2><div class="grid"><div><label>Nombre</label><input id="pn"></div><div><label>Precio $</label><input id="pr" type="number" min="0"></div><div><label>Piezas</label><input id="ps" type="number" min="0"></div><div><label>Costo $</label><input id="pc" type="number" min="0"></div><div><label>Código de barras</label><input id="pb"></div></div><br><button class="btn p" onclick="addP()">Agregar producto</button></div>`}
function addP(){const n=$("pn").value.trim();if(!n)return toast("Escribe el nombre");S.products.push({id:Date.now(),n,p:+$("pr").value||0,s:parseInt($("ps").value)||0,d:0,cost:+$("pc").value||0,c:$("pb").value.trim(),min:3});save();toast("Producto agregado");render()}
function delP(id){S.products=S.products.filter(x=>x.id!=id);tk=tk.filter(x=>x.id!=id);save();render()}
function chart(t,type){const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);days.push(ymd(d))}
const v=days.map(k=>S.sales.filter(x=>x.iso==k&&x.type==type).reduce((s,x)=>s+x.amt,0)),m=Math.max(...v,1);
return`<div class="card"><h2>${t}: $${v.reduce((a,b)=>a+b,0)} (últimos 7 días)</h2><svg viewBox="0 0 350 150" style="width:100%">${v.map((n,i)=>{const h=n/m*90;return`<rect x="${i*50+8}" y="${115-h}" width="34" height="${h}" rx="4" fill="var(--p)"/><text x="${i*50+25}" y="${108-h}" font-size="10" text-anchor="middle" fill="var(--tx)">${n?"$"+n:""}</text><text x="${i*50+25}" y="132" font-size="10" text-anchor="middle" fill="var(--mu)">${days[i].slice(5)}</text>`}).join("")}</svg></div>`}
function tGraf(){return chart("Ventas de cortes y servicios","corte")+chart("Ventas de productos","producto")+commCard()+'<p class="mu">Los cortes se cuentan al marcar la cita como completada; los productos, al completar la cita o cobrar en el punto de venta.</p>'}
function tLoy(){const cl=S.users.filter(u=>u.role=="client");return`<div class="card"><h2>Programa de puntos</h2><div class="grid"><div><label>Puntos para un servicio gratis</label><input type="number" min="1" value="${S.loy.need}" onchange="S.loy.need=Math.max(1,+this.value||1);save();toast('Guardado')"></div><div><label>Puntos por cita completada</label><input type="number" min="1" value="${S.loy.per}" onchange="S.loy.per=Math.max(1,+this.value||1);save();toast('Guardado')"></div></div></div>
${lvCard()}<div class="card"><h2>Clientes</h2>${cl.length?`<table><tr><th>Cliente</th><th>Correo</th><th>Puntos</th><th>Nivel de precio</th></tr>${cl.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><input type="number" min="0" value="${u.pts||0}" onchange="S.users.find(c=>c.email=='${esc(u.email)}').pts=Math.max(0,+this.value||0);save();toast('Guardado')"></td><td><select onchange="lvSet('${esc(u.email)}',this.value)">${lvOpts(u.lv)}</select></td></tr>`).join("")}</table>`:'<p class="mu">Aún no hay clientes registrados.</p>'}</div>`}
function tDis(){const s=S.shop;return`<div class="card"><h2>Colores de la plantilla</h2><div class="grid"><div><label>Color principal</label><input id="c1" type="color" value="${s.color}"></div><div><label>Fondo</label><input id="c2" type="color" value="${s.bg||"#faf8f5"}"></div><div><label>Tarjetas</label><input id="c3" type="color" value="${s.card||"#ffffff"}"></div><div><label>Texto</label><input id="c4" type="color" value="${s.tx||"#1d1b18"}"></div></div><h2 style="margin-top:14px">Modo oscuro</h2><div class="grid"><div><label>Fondo oscuro</label><input id="c5" type="color" value="${s.dbg||"#17150f"}"></div><div><label>Tarjetas oscuras</label><input id="c6" type="color" value="${s.dcard||"#221f18"}"></div><div><label>Texto oscuro</label><input id="c7" type="color" value="${s.dtx||"#f3efe8"}"></div></div><p class="mu">Cambia entre claro y oscuro con el botón 🌓 del menú.</p></div>
<div class="card"><h2>Datos del negocio</h2><div class="grid"><div><label>Nombre</label><input id="cn" value="${esc(s.name)}"></div><div><label>Dirección</label><input id="ca" value="${esc(s.addr)}"></div><div><label>Teléfono</label><input id="ct" value="${esc(s.tel)}"></div><div><label>Horario</label><input id="ch" value="${esc(s.hours)}"></div><div><label>WhatsApp para avisos (con lada, solo números)</label><input id="cw" value="${esc(s.wa)}" placeholder="5215512345678"></div><div><label>Correo para avisos</label><input id="cm" value="${esc(s.mail)}"></div><div><label>Enlace de Instagram</label><input id="ci" value="${esc(s.ig)}"></div><div><label>Enlace para reseñas en Google</label><input id="cg" value="${esc(s.gmb)}"></div><div><label>WhatsApp del proveedor (solo números)</label><input id="cv" value="${esc(s.prov)}"></div></div><br><button class="btn p" onclick="saveShop()">Guardar</button> <button onclick="resetColors()">Restablecer colores</button></div>`}
function saveShop(){Object.assign(S.shop,{color:$("c1").value,bg:$("c2").value,card:$("c3").value,tx:$("c4").value,name:$("cn").value,addr:$("ca").value,tel:$("ct").value,hours:$("ch").value,dbg:$("c5").value,dcard:$("c6").value,dtx:$("c7").value,wa:$("cw").value.replace(/\D/g,""),mail:$("cm").value.trim(),ig:$("ci").value.trim(),gmb:$("cg").value.trim(),prov:$("cv").value.replace(/\D/g,"")});save();toast("Guardado");render()}
function resetColors(){Object.assign(S.shop,{color:"#c8973a",bg:"",card:"",tx:"",dbg:"",dcard:"",dtx:""});save();render()}
function toggleTheme(){const dk=S.theme=="dark"||(S.theme=="auto"&&matchMedia("(prefers-color-scheme: dark)").matches);S.theme=dk?"light":"dark";save();render()}
// ---- Avisos por WhatsApp / correo (abren el mensaje ya escrito; el envío automático requiere servidor) ----
const apptMsg=(x,tag)=>`${tag}: ${x.client}${whoTxt(x)} · ${x.service}${x.free?" (gratis)":""} · ${x.date} ${x.time} · Pago: ${x.pay=="linea"?"en línea":"efectivo"} · ${x.items.length?(x.status=="completada"?"Compró: ":"Va a comprar: ")+x.items.map(i=>i.q+" x "+i.n).join(", "):"Sin productos"}`;
const sendLinks=t=>`${S.shop.wa?`<a href="https://wa.me/${S.shop.wa}?text=${encodeURIComponent(t)}" target="_blank" rel="noopener">WhatsApp</a>`:""} ${S.shop.mail?`<a href="mailto:${esc(S.shop.mail)}?subject=${encodeURIComponent("Aviso de cita")}&body=${encodeURIComponent(t)}" target="_blank" rel="noopener">Correo</a>`:""}`;
function assignA(i,v){const x=S.appts[i];x.staff=+v;if(x.staff)S.notifs.push({t:apptMsg(x,"Cita asignada a ti"),read:false,staff:x.staff});save();toast("Asignada")}
// ---- Permisos de empleados ----
function permsRowOld(id){const u=S.users.find(x=>x.staffId==id);if(!u)return"";const o=[["allCitas","Ver todas las citas"],["graf","Ver gráficas de ventas"],["gastos","Panel de gastos"]];return`<p class="mu">Permisos de ${esc(u.user)} (por defecto solo ve sus citas y avisos):</p><div class="row">${o.map(([k,l])=>`<label class="row" style="margin:0"><input type="checkbox" style="width:auto"${u.perms&&u.perms[k]?" checked":""} onchange="setPerm(${id},'${k}',this.checked)"> ${l}</label>`).join("")}</div>`}
function setPerm(id,k,v){const u=S.users.find(x=>x.staffId==id);u.perms=u.perms||{};u.perms[k]=v;save();toast("Permiso guardado")}
function staffExtra(){const m=S.notifs.filter(n=>n.staff==S.me.staffId).slice(-5).reverse();return`<div class="card"><h2>Mis avisos</h2>${m.map(n=>`<div class="mu">${esc(n.t)}</div>`).join("")||'<span class="mu">Sin avisos</span>'}</div><div class="card"><h2>Mis servicios</h2>${svPanel(S.me.staffId,false)}</div>${P("design")?tDesign():""}${P("graf")?tGraf():""}${P("gastos")?expView(false):""}`}
// ---- Gastos ----
function expView(adm){const m=ymd(new Date()).slice(0,7),tx=S.exp.filter(x=>x.iso.slice(0,7)==m).reduce((s,x)=>s+x.amt,0),ms=S.sales.filter(x=>x.iso.slice(0,7)==m),inc=ms.reduce((s,x)=>s+x.amt,0),cst=ms.reduce((s,x)=>s+(x.cost||0),0);return`<div class="card"><h2>Gastos</h2><div class="grid"><div><label>Concepto</label><input id="xc"></div><div><label>Monto $</label><input id="xa" type="number" min="0"></div><div><label>Fecha</label><input id="xd" type="date" value="${ymd(new Date())}"></div></div><br><button class="btn p" onclick="addExp()">Registrar gasto</button><p>Gastos del mes: <b>$${tx}</b>${adm?` · Ventas del mes: $${inc} · Costo de productos: $${cst} · Utilidad real: <b>$${inc-cst-tx}</b>`:""}</p>${S.exp.slice(-15).reverse().map(x=>`<div class="mu">${x.iso} · ${esc(x.c)} — $${x.amt} (${esc(x.by)})${adm?` <button onclick="delExp(${x.id})">Quitar</button>`:""}</div>`).join("")||'<span class="mu">Sin gastos</span>'}</div>`}
function addExp(){const c=$("xc").value.trim(),a=+$("xa").value;if(!c||!a)return toast("Escribe concepto y monto");S.exp.push({id:Date.now(),iso:$("xd").value||ymd(new Date()),c,amt:a,by:S.me.name});save();toast("Gasto registrado");render()}
function delExp(id){S.exp=S.exp.filter(x=>x.id!=id);save();render()}
// ---- Niveles de precio ----
const lvOpts=sel=>`<option value="0">Normal</option>`+S.levels.map(l=>`<option value="${l.id}"${l.id==sel?" selected":""}>${esc(l.n)} (-${l.d}%)</option>`).join("");
function lvSet(email,v){S.users.find(u=>u.email==email).lv=+v;save();toast("Nivel asignado")}
function lvCard(){return`<div class="card"><h2>Niveles de precio</h2><p class="mu">El descuento del nivel se suma al del producto o servicio. Tú decides qué clientes tienen cada nivel.</p>${S.levels.map(l=>`<div class="row"><input value="${esc(l.n)}" onchange="lvEd(${l.id},'n',this.value)" style="flex:1"><input type="number" min="0" max="100" value="${l.d}" onchange="lvEd(${l.id},'d',this.value)" style="width:90px"> %</div>`).join("")}<div class="row"><input id="ln" placeholder="Nuevo nivel (ej. Cliente VIP)" style="flex:1"><input id="ld" type="number" placeholder="%" style="width:90px"><button class="btn p" onclick="addLv()">Agregar</button></div></div>`}
function lvEd(id,k,v){const l=S.levels.find(x=>x.id==id);l[k]=k=="n"?v:Math.max(0,Math.min(100,+v||0));save();toast("Guardado")}
function addLv(){const n=$("ln").value.trim();if(!n)return toast("Escribe el nombre");S.levels.push({id:Date.now(),n,d:Math.min(100,+$("ld").value||0)});save();render()}
// ---- Agenda con horarios disponibles ----
const t2m=t=>{const[a,b]=t.split(":");return+a*60+ +b};
const m2t=m=>String(Math.floor(m/60)).padStart(2,"0")+":"+String(m%60).padStart(2,"0");
function slotsOld(d,sf,dur){const c=S.sch;if(!d||S.blocked.includes(d))return[];const o=t2m(c.o),e=t2m(c.c),bs=t2m(c.bs),be=t2m(c.be),out=[],now=new Date();
for(let m=o;m+dur<=e;m+=c.step){if(bs<be&&m<be&&m+dur>bs)continue;if(d==ymd(now)&&m<=now.getHours()*60+now.getMinutes())continue;
const ov=S.appts.filter(x=>x.status!="cancelada"&&x.date==d&&t2m(x.time)<m+dur&&m<t2m(x.time)+(x.m||30));
if(sf?ov.some(x=>x.staff==sf):ov.length>=Math.max(1,S.staff.length))continue;out.push(m2t(m))}return out}
function refSlotsOld(){const sv=S.services.find(x=>x.id==$("sv").value),l=slots($("d").value,+$("sf").value,sv.m);$("h").innerHTML=l.length?l.map(t=>`<option>${t}</option>`).join(""):'<option value="">Sin horarios</option>'}
const waTo=(tel,t)=>{let d=String(tel).replace(/\D/g,"");if(d.length==10)d="52"+d;return`https://wa.me/${d}?text=${encodeURIComponent(t)}`};
function tAgenda(){const c=S.sch,tmr=ymd(new Date(Date.now()+864e5)),rm=S.appts.filter(x=>x.date==tmr&&x.status!="cancelada");
return`<div class="card"><h2>Horario del negocio</h2><div class="grid">${[["o","Apertura","time"],["c","Cierre","time"],["bs","Descanso inicia","time"],["be","Descanso termina","time"],["step","Intervalo (min)","number"]].map(([k,l,t])=>`<div><label>${l}</label><input type="${t}" value="${c[k]}" onchange="S.sch['${k}']=this.type=='number'?Math.max(10,+this.value||30):this.value;save();toast('Guardado')"></div>`).join("")}</div></div>
<div class="card"><h2>Días de trabajo</h2><div class="row">${["Dom","Lun","Mar","Mié","Jue","Vie","Sáb"].map((n,i)=>`<label class="row" style="margin:0"><input type="checkbox" style="width:auto"${c.days.includes(i)?" checked":""} onchange="dayTg(${i},this.checked)"> ${n}</label>`).join("")}</div></div>
<div class="card"><h2>Días bloqueados (vacaciones, festivos)</h2><div class="row"><input id="bk" type="date" style="width:auto"><button class="btn p" onclick="const v=$('bk').value;if(v&&!S.blocked.includes(v)){S.blocked.push(v);save();render()}">Bloquear día</button></div>${S.blocked.map(b=>`<span class="tag" style="margin:2px">${b} <a href="#" onclick="S.blocked=S.blocked.filter(x=>x!='${b}');save();render();return false" style="color:#fff">✕</a></span>`).join("")||'<span class="mu">Sin días bloqueados</span>'}</div>
<div class="card"><h2>Recordatorios para mañana (${tmr})</h2>${rm.map(x=>{const u=S.users.find(k=>k.email==x.email);return`<div class="mu">${x.time} · ${esc(x.client)} · ${esc(x.service)} ${u&&u.tel?`<a href="${waTo(u.tel,"Hola "+x.client+", te recordamos tu cita en "+S.shop.name+" mañana "+x.date+" a las "+x.time+" ("+x.service+").")}" target="_blank" rel="noopener">Enviar WhatsApp</a>`:"(sin teléfono)"}</div>`}).join("")||'<span class="mu">Sin citas mañana</span>'}</div>`}
// ---- Galería, reseñas ----
const galItem=(g,adm)=>`<div class="card"><div class="row">${g.a?`<img src="${g.a}" style="width:48%;border-radius:8px">`:""}${g.b?`<img src="${g.b}" style="width:48%;border-radius:8px">`:""}</div><div class="mu">${g.a&&g.b?"Antes / Después · ":""}${esc(g.t)}</div>${adm?`<button onclick="S.gal=S.gal.filter(x=>x.id!=${g.id});save();render()">Quitar</button>`:""}</div>`;
const rd=(f,png,mx=500)=>new Promise(r=>{if(!f)return r("");const fr=new FileReader();fr.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,mx/Math.max(i.width,i.height)),c=document.createElement("canvas");c.width=i.width*k;c.height=i.height*k;c.getContext("2d").drawImage(i,0,0,c.width,c.height);r(png?c.toDataURL("image/png"):c.toDataURL("image/jpeg",.7))};i.onerror=()=>r("");i.src=fr.result};fr.onerror=()=>r("");fr.readAsDataURL(f)});
async function addGal(){const a=await rd($("g1").files[0]),b=await rd($("g2").files[0]);if(!a&&!b)return toast("Elige al menos una foto");S.gal.push({id:Date.now(),t:$("gt").value,a,b});save();render()}
function tGal(){return`<div class="card"><h2>Galería de trabajos</h2><div class="grid"><div><label>Descripción</label><input id="gt"></div><div><label>Foto antes</label><input id="g1" type="file" accept="image/*"></div><div><label>Foto después</label><input id="g2" type="file" accept="image/*"></div></div><br><button class="btn p" onclick="addGal()">Agregar a la galería</button><p class="mu">Las fotos se comprimen. En el demo se guardan en el navegador (espacio limitado).</p></div><div class="card"><div class="grid">${S.gal.map(g=>galItem(g,true)).join("")||'<span class="mu">Sin fotos</span>'}</div></div>`}
function homeExtra(){const r=S.rev,av=r.length?(r.reduce((s,x)=>s+x.s,0)/r.length).toFixed(1):0;
return`${S.gal.length?`<div class="card"><h2>Nuestros trabajos</h2><div class="grid">${S.gal.map(g=>galItem(g,false)).join("")}</div></div>`:""}${r.length?`<div class="card"><h2>Reseñas ★ ${av} (${r.length})</h2>${r.slice(-4).reverse().map(x=>`<div class="mu">${"★".repeat(x.s)} ${esc(x.n)}: ${esc(x.t)}</div>`).join("")}</div>`:""}${S.shop.gmb?`<div class="card hero" style="padding:12px">${S.shop.gmb?`<a href="${esc(S.shop.gmb)}" target="_blank" rel="noopener">Déjanos una reseña en Google</a>`:""}</div>`:""}`}
let rvId=0;
const rate=id=>{rvId=id;render()};
const rvForm=()=>rvId?`<div class="card"><h2>Tu reseña</h2><label>Estrellas</label><select id="rs">${[5,4,3,2,1].map(n=>`<option value="${n}">${"★".repeat(n)}</option>`).join("")}</select><label>Comentario</label><input id="rt"><br><br><button class="btn p" onclick="sendRev()">Enviar reseña</button></div>`:"";
function sendRev(){const x=S.appts.find(a=>a.id==rvId);S.rev.push({id:Date.now(),n:S.me.name,s:+$("rs").value,t:$("rt").value,staff:x.staff});x.rv=true;rvId=0;save();toast("¡Gracias por tu reseña!");render()}
// ---- Punto de venta: código de barras, servicios ----
function scan(v){const p=S.products.find(x=>x.c&&x.c==v.trim());if(!p)return toast("Código no encontrado");tkAdd(p.id);const b=$("bc");if(b)b.focus()}
const svAdd=v=>{if(v){sk.push(+v);render()}};
// ---- Comisiones y corte de caja ----
function commCard(){const m=ymd(new Date()).slice(0,7);return`<div class="card"><h2>Ventas y comisiones por empleado (mes)</h2><div class="scroll"><table><tr><th>Empleado</th><th>Servicios</th><th>Productos</th><th>Propinas</th><th>Comisión ${S.shop.comm}%</th></tr>${S.staff.map(s=>{const l=S.sales.filter(x=>x.sid==s.id&&x.iso.slice(0,7)==m),a=t=>l.filter(x=>x.type==t).reduce((z,x)=>z+x.amt,0),tp=l.reduce((z,x)=>z+(x.tip||0),0);return`<tr><td>${esc(s.n)}</td><td>$${a("corte")}</td><td>$${a("producto")}</td><td>$${tp}</td><td>$${Math.round((a("corte")+a("producto"))*S.shop.comm/100)}</td></tr>`}).join("")}</table></div><div class="row"><label style="margin:0">% de comisión</label><input type="number" min="0" max="100" value="${S.shop.comm}" style="width:90px" onchange="S.shop.comm=Math.max(0,+this.value||0);save();render()"></div></div>`}
const cj=()=>{const t=ymd(new Date()),l=S.sales.filter(x=>x.iso==t);return{t,ef:l.filter(x=>x.pay=="efectivo").reduce((s,x)=>s+x.amt+(x.tip||0),0),tj:l.filter(x=>x.pay&&x.pay!="efectivo").reduce((s,x)=>s+x.amt+(x.tip||0),0),gs:S.exp.filter(x=>x.iso==t).reduce((s,x)=>s+x.amt,0)}};
function tCorte(){const c=cj();return`<div class="card"><h2>Corte de caja de hoy (${c.t})</h2><p>Efectivo: <b>$${c.ef}</b><br>Tarjeta / en línea: <b>$${c.tj}</b><br>Gastos del día: $${c.gs}<br>Efectivo esperado en caja: <b id="exp">$${c.ef-c.gs}</b></p><div class="grid"><div><label>Fondo inicial $</label><input id="fi" type="number" min="0" value="0" oninput="cc()"></div><div><label>Efectivo contado $</label><input id="ec" type="number" min="0" oninput="cc()"></div></div><p id="dif"></p></div>`}
function cc(){const c=cj(),e=c.ef-c.gs+(+$("fi").value||0),k=$("ec").value;$("exp").textContent="$"+e;$("dif").textContent=k===""?"":"Diferencia: $"+(+k-e)+(+k==e?" ✔ cuadra":" (sobra o falta)")}
// ---- Agenda del cliente, cita para otra persona y acompañantes ----
let comp=[];
const whoTxt=x=>(x.for?` (cita para ${x.for.n}, ${x.for.t})`:"")+(x.comp&&x.comp.length?` · Acompañantes: ${x.comp.map(c=>c.t+(c.n?" "+c.n:"")+(c.s?" +servicio":"")).join(", ")}`:"");
function drawComp(){const e=$("cp");if(e)e.innerHTML=comp.map((c,i)=>`<div class="row"><select onchange="comp[${i}].t=this.value;refSlots()" style="width:auto"><option${c.t=="Adulto"?" selected":""}>Adulto</option><option${c.t=="Niño"?" selected":""}>Niño</option></select><select onchange="comp[${i}].s=this.value;refSlots()" style="width:auto"><option value="">Solo acompaña</option>${S.services.map(s=>`<option value="${s.id}"${s.id==c.s?" selected":""}>${esc(s.n)}</option>`).join("")}</select><input placeholder="Nombre (opcional)" value="${esc(c.n)}" onchange="comp[${i}].n=this.value" style="flex:1"><button type="button" onclick="comp.splice(${i},1);drawComp();refSlots()">Quitar</button></div>`).join("")}
const addComp=()=>{comp.push({t:"Adulto",n:"",s:""});drawComp();refSlots()};
const whoCh=()=>{$("ot").classList.toggle("hidden",$("who").value!="other");refSlots()};
const agendaCard=l=>{const t=ymd(new Date()),u=l.filter(x=>x.status!="cancelada"&&x.status!="completada"&&x.date>=t).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(!u.length)return"";
return`<div class="card"><h2>📅 Mi agenda (próximas citas)</h2>${u.map(x=>`<div class="row"><b>${x.date} ${x.time}</b> · ${esc(x.service)} · ${esc(staffName(x.staff))}<span class="mu">${esc(whoTxt(x))}</span></div>`).join("")}<div class="row"><button class="btn p" onclick="bookFor(0)">Agendar otra cita</button><button class="btn" onclick="bookFor(1)">Agendar para otra persona</button><button class="btn" onclick="bookFor(2)">Agendar con acompañante</button></div></div>`};
const bookFor=m=>{go("book");if(m==1){$("who").value="other";whoCh()}if(m==2)addComp()};
// ---- Calendario con disponibilidad, horarios por empleado y duración ----
const win=s=>[t2m(s&&s.so||S.sch.o),t2m(s&&s.sc||S.sch.c)];
const outWin=x=>{const s=S.staff.find(k=>k.id==x.staff);if(!s)return false;const[a,b]=win(s),m=t2m(x.time);return m<a||m+(x.m||30)>b};
function info(d,sf,dur,ex,sid){const c=S.sch,now=new Date(),td=ymd(now),out=[];if(!d||d<td||S.blocked.includes(d)||!c.days.includes(new Date(d+"T12:00").getDay()))return out;
const bs=t2m(c.bs),be=t2m(c.be),o=t2m(c.o),e=t2m(c.c);
for(let m=o;m+dur<=e;m+=c.step){if(bs<be&&m<be&&m+dur>bs)continue;let st="free";
if(d==td&&m<=now.getHours()*60+now.getMinutes())st="past";else{const ov=S.appts.filter(x=>x.id!=ex&&x.status!="cancelada"&&x.date==d&&t2m(x.time)<m+dur&&m<t2m(x.time)+(x.m||30)),wk=S.staff.filter(s=>{const[a,b]=win(s);return does(s,sid)&&m>=a&&m+dur<=b});
st=sf?(wk.some(s=>s.id==sf)&&!ov.some(x=>x.staff==sf)?"free":"busy"):(S.staff.length?(wk.length>ov.length?"free":"busy"):(ov.length?"busy":"free"))}
out.push({t:m2t(m),st})}return out}
const slots=(d,sf,dur,ex,sid)=>info(d,sf,dur,ex,sid).filter(x=>x.st=="free").map(x=>x.t);
const bookDur=()=>{const g=id=>S.services.find(x=>x.id==id);return g($("sv").value).m+comp.reduce((s,c)=>s+(c.s?g(c.s).m:0),0)};
const prK=(s,t)=>t=="Niño"&&s.pk>0?Math.round(s.pk*(100-Math.min(100,(s.d||0)+lvd()))/100):pr(s);
let cY=new Date().getFullYear(),cM=new Date().getMonth();
function refSlots(){if(!$("cal"))return;const sv=S.services.find(x=>x.id==$("sv").value);fillStaff(sv.id);const sf=+$("sf").value,dur=bookDur(),td=ymd(new Date()),d=$("d").value;
const first=new Date(cY,cM,1),n=new Date(cY,cM+1,0).getDate(),off=(first.getDay()+6)%7;
let h=`<div class="row"><button type="button" onclick="calGo(-1)">◀</button><b style="flex:1;text-align:center;text-transform:capitalize">${first.toLocaleDateString("es-MX",{month:"long",year:"numeric"})}</b><button type="button" onclick="calGo(1)">▶</button></div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px;text-align:center">${["L","M","M","J","V","S","D"].map(x=>`<span class="mu">${x}</span>`).join("")}`+"<span></span>".repeat(off);
for(let i=1;i<=n;i++){const k=cY+"-"+String(cM+1).padStart(2,"0")+"-"+String(i).padStart(2,"0"),all=info(k,sf,dur,0,sv.id),fr=all.filter(x=>x.st=="free").length;let bg,dis=true;
if(k<td||!all.length)bg="#9e9e9e";else if(!fr)bg="#c0392b";else{dis=false;bg=fr/all.length<=.4?"#e0a100":"#2e7d32"}
h+=`<button type="button"${dis?" disabled":""} onclick="pickD('${k}')" style="padding:8px 0;color:#fff;background:${bg};opacity:${dis?.45:1};border:${k==d?"3px solid var(--tx)":"1px solid var(--bd)"}">${i}</button>`}
$("cal").innerHTML=h+`</div><p class="mu">🟩 Muchos horarios · 🟨 Pocos · 🟥 Lleno · ⬜ No disponible</p>`;
const l=d?info(d,sf,dur,0,sv.id):[];if($("h").value&&!l.some(x=>x.t==$("h").value&&x.st=="free"))$("h").value="";
$("tm").innerHTML=!d?'<span class="mu">Elige un día en el calendario</span>':l.length?l.map(x=>`<button type="button"${x.st=="free"?"":" disabled"} onclick="pickT('${x.t}')" style="${x.st!="free"?"text-decoration:line-through;opacity:.5;":""}${x.t==$("h").value?"background:var(--p);color:#fff;":""}">${x.t}${x.st=="busy"?" · Ocupada":x.st=="past"?" · Pasó":""}</button>`).join(""):'<span class="mu">Día no disponible</span>';
const wt=$("who").value=="other"?$("ok").value:"Adulto",pc=($("fr")&&$("fr").checked?0:prK(sv,wt))+comp.reduce((s,c)=>{const z=c.s&&S.services.find(x=>x.id==c.s);return s+(z?prK(z,c.t):0)},0);
$("tot").textContent="Duración: "+dur+" min · Servicios: $"+pc}
function calGo(n){const t=new Date();cM+=n;if(cM<0){cM=11;cY--}if(cM>11){cM=0;cY++}if(cY<t.getFullYear()||(cY==t.getFullYear()&&cM<t.getMonth())){cY=t.getFullYear();cM=t.getMonth()}refSlots()}
const pickD=k=>{$("d").value=k;$("h").value="";refSlots()};
const pickT=t=>{$("h").value=t;refSlots()};
const dayTg=(i,v)=>{S.sch.days=S.sch.days.filter(x=>x!=i);if(v)S.sch.days.push(i);save();toast("Guardado")};
// Al cambiar la duración de una cita se recorren las siguientes del mismo empleado y día
function shiftFrom(i){const x=S.appts[i],l=S.appts.filter(a=>a.staff==x.staff&&a.date==x.date&&a.status!="cancelada").sort((a,b)=>t2m(a.time)-t2m(b.time)),k=l.indexOf(x);let cur=t2m(x.time)+(x.m||30),mv=0;
for(let j=k+1;j<l.length;j++){const a=l[j];if(t2m(a.time)<cur){a.time=m2t(cur);mv++;S.notifs.push({t:apptMsg(a,"Cita reprogramada por cambio de duración"),read:false,staff:a.staff})}cur=t2m(a.time)+(a.m||30)}
if(cur>t2m(S.sch.c))S.notifs.push({t:"Aviso: las citas del "+x.date+" ahora terminan después del cierre ("+m2t(cur)+").",read:false});save();return mv}
function setDur(i,v){const x=S.appts[i];x.m=Math.max(5,+v||30);const mv=x.staff?shiftFrom(i):(save(),0);toast(mv?"Duración actualizada; "+mv+" cita(s) siguientes se recorrieron":"Duración actualizada");render()}
function svMin(s,dl){if(!dl)return;const t=ymd(new Date()),f=x=>x.service==s.n&&x.date>=t&&["pendiente","confirmada"].includes(x.status);S.appts.filter(f).forEach(x=>x.m=Math.max(5,(x.m||30)+dl));S.appts.filter(x=>f(x)&&x.staff).forEach(x=>shiftFrom(S.appts.indexOf(x)))}
function resch(i,k,v){const x=S.appts[i],d=k=="date"?v:x.date,t=k=="time"?v:x.time;if(!v)return render();if(!info(d,x.staff,x.m||30,x.id).some(s=>s.t==t&&s.st=="free")){toast("Ese horario no está disponible");return render()}
x[k]=v;S.notifs.push({t:apptMsg(x,"Cita reprogramada"),read:false,staff:x.staff});save();toast("Cita reprogramada");render()}
// ---- Empleados: servicios que realiza, permisos, acceso y caja ----
const does=(s,id)=>!id||!s.sv||!s.sv.length||s.sv.includes(+id);
function fillStaff(id){const e=$("sf"),c=e.value;e.innerHTML='<option value="0">Sin preferencia</option>'+S.staff.filter(s=>does(s,id)).map(s=>`<option value="${s.id}">${esc(s.n)} (Estación ${s.st})${s.bio?" - "+esc(s.bio):""}</option>`).join("");if([...e.options].some(o=>o.value==c))e.value=c}
const userTaken=(u,ex)=>S.users.some(x=>x!==ex&&((x.user||"").toLowerCase()==u.toLowerCase()||(x.email||"").toLowerCase()==u.toLowerCase()));
function addStaff(){const n=$("sn").value.trim(),u=$("su").value.trim(),p=$("sp").value;if(!n)return toast("Escribe el nombre");if(u&&!p)return toast("Escribe también la contraseña");if(u&&userTaken(u))return toast("Ese usuario ya existe");
const id=Date.now();S.staff.push({id,n,st:+$("ss").value||S.staff.length+1,tel:"",bio:"",sv:[]});if(u)S.users.push({user:u,pass:p,name:n,role:"staff",staffId:id,perms:{pos:true,caja:true}});save();toast("Empleado agregado");render()}
function setAccess(id){const u=$("au"+id).value.trim(),p=$("ap"+id).value,s=S.staff.find(x=>x.id==id);let us=S.users.find(x=>x.staffId==id);if(!u)return toast("Escribe el usuario");if(userTaken(u,us))return toast("Ese usuario ya existe");
if(!us){if(!p)return toast("Escribe la contraseña");us={user:u,pass:p,name:s.n,role:"staff",staffId:id,perms:{pos:true,caja:true}};S.users.push(us)}else{us.user=u;if(p)us.pass=p}save();toast("Acceso guardado");render()}
function permsRow(id){const us=S.users.find(x=>x.staffId==id),g=[["Página",[["allCitas","Ver todas las citas"],["graf","Ver gráficas y comisiones"],["gastos","Panel de gastos"],["svEdit","Agregar y editar sus servicios (precio y duración)"],["design","Editar inicio y diseño (logo, imágenes, redes, promociones)"]]],["Punto de venta",[["pos","Usar el punto de venta"],["inv","Surtir y editar productos"],["corte","Ver el corte de caja general"],["caja","Caja propia para cobrar sus citas"]]]];
return`<details><summary>Acceso (usuario y contraseña)</summary><div class="grid"><div><label>Usuario</label><input id="au${id}" value="${esc(us?us.user:"")}"></div><div><label>${us?"Nueva contraseña (vacío = no cambiar)":"Contraseña"}</label><input id="ap${id}" type="password"></div></div><br><button class="btn p" onclick="setAccess(${id})">Guardar acceso</button></details><details><summary>Servicios que realiza</summary>${svPanel(id,true)}</details><details><summary>Permisos de página y punto de venta</summary>${us?g.map(([t,o])=>`<p class="mu"><b>${t}</b></p><div class="row">${o.map(([k,l])=>`<label class="row" style="margin:0"><input type="checkbox" style="width:auto"${us.perms&&us.perms[k]?" checked":""} onchange="setPerm(${id},'${k}',this.checked)"> ${l}</label>`).join("")}</div>`).join(""):'<p class="mu">Primero asígnale usuario y contraseña en Acceso.</p>'}<p class="mu">Por defecto un empleado solo ve sus citas y avisos.</p></details>`}
function svPanel(id,adm){const s=S.staff.find(x=>x.id==id),ed2=adm||P("svEdit"),mine=s.sv||[];
return`<p class="mu">Marca lo que realiza (si no marca ninguno, realiza todos). ${ed2?(adm?"":"Puedes editar precio y duración de los marcados."):""}</p><div class="scroll"><table><tr><th>Realiza</th><th>Servicio</th>${ed2?"<th>Precio $</th><th>Min</th>":""}</tr>${S.services.map(v=>{const on=mine.includes(v.id);return`<tr><td><input type="checkbox" style="width:auto"${on?" checked":""} onchange="svTg(${id},${v.id},this.checked,${adm?1:0})"></td><td>${esc(v.n)}</td>${ed2?(adm||on?numIn("services",v,"p")+numIn("services",v,"m"):"<td></td><td></td>"):""}</tr>`}).join("")}</table></div>${ed2?`<div class="grid"><div><label>Nuevo servicio</label><input id="nn${id}"></div><div><label>Precio $</label><input id="np${id}" type="number" min="0"></div><div><label>Minutos</label><input id="nm${id}" type="number" min="5"></div></div><br><button class="btn p" onclick="addSvS(${id})">Agregar servicio</button>`:""}`}
function svTg(id,v,on,adm){const s=S.staff.find(x=>x.id==id);s.sv=(s.sv||[]).filter(x=>x!=v);if(on)s.sv.push(v);save();toast("Guardado");if(!adm)render()}
function addSvS(id){const n=$("nn"+id).value.trim();if(!n)return toast("Escribe el nombre");const v={id:Date.now(),n,p:+$("np"+id).value||0,m:+$("nm"+id).value||30,d:0,pk:0},s=S.staff.find(x=>x.id==id);S.services.push(v);s.sv=(s.sv||[]).concat(v.id);save();toast("Servicio agregado");render()}
// Caja propia del empleado
function vCaja(a){if(!S.me||S.me.role!="staff"||!P("caja"))return go("login");const id=S.me.staffId,t=ymd(new Date()),mine=S.appts.map((x,i)=>[x,i]).filter(([x])=>x.staff==id&&x.date==t&&["pendiente","confirmada"].includes(x.status));
const l=S.sales.filter(x=>x.sid==id&&x.iso==t),ef=l.filter(x=>x.pay=="efectivo").reduce((s,x)=>s+x.amt+(x.tip||0),0),tj=l.filter(x=>x.pay&&x.pay!="efectivo").reduce((s,x)=>s+x.amt+(x.tip||0),0),tp=l.reduce((s,x)=>s+(x.tip||0),0),vt=l.reduce((s,x)=>s+x.amt,0);
a.innerHTML=`<div class="card"><h2>Mi caja · cobrar mis citas de hoy</h2>${mine.map(([x,i])=>`<div class="row"><span style="flex:1"><b>${x.time}</b> ${esc(x.client)} · ${esc(x.service)} · $${x.sp+x.items.reduce((s,t)=>s+t.p*t.q,0)}</span><select id="cm${i}" style="width:auto"><option value="efectivo">Efectivo</option><option value="linea">Tarjeta</option></select><input id="ct${i}" type="number" min="0" placeholder="Propina" style="width:90px"><button class="btn p" onclick="cobrarCita(${i})">Cobrar</button></div>`).join("")||'<span class="mu">No tienes citas por cobrar hoy.</span>'}</div>
<div class="card"><h2>Mi caja de hoy</h2><p>Efectivo: <b>$${ef}</b> · Tarjeta: <b>$${tj}</b> · Propinas: $${tp}<br>Ventas de mis servicios y productos: $${vt} · Comisión estimada (${S.shop.comm}%): $${Math.round(vt*S.shop.comm/100)}</p><div class="grid"><div><label>Fondo inicial $</label><input id="mf" type="number" min="0" value="0" oninput="mc(${ef})"></div><div><label>Efectivo contado $</label><input id="mk" type="number" min="0" oninput="mc(${ef})"></div></div><p id="md"></p></div>`}
function mc(ef){const k=$("mk").value,e=ef+(+$("mf").value||0);$("md").textContent=k===""?"":"Esperado: $"+e+" · Diferencia: $"+(+k-e)+(+k==e?" ✔ cuadra":"")}
function cobrarCita(i){const x=S.appts[i];x.pay=$("cm"+i).value;x.tip=Math.max(0,+$("ct"+i).value||0);x.cobro=S.me.staffId;const e=$("cx"+i),pid=e?+e.value:0;if(pid){const p=prod(pid);if(!p||p.s<1)return toast("Sin piezas de ese producto");p.s--;const t=x.items.find(z=>z.id==pid);if(t)t.q++;else x.items.push({id:pid,n:p.n,q:1,p:pr(p),c:p.cost||0})}setSt(i,"completada")}
// Completar la venta desde la agenda del empleado
function saleCell(x){const i=S.appts.indexOf(x);if(x.status=="completada")return`✔ Venta completada${x.tip?" · propina $"+x.tip:""}`;
if(x.staff!=S.me.staffId)return x.status;
if(!P("caja"))return x.status+' <span class="mu">(sin permiso de caja)</span>';
if(x.date>ymd(new Date()))return x.status+' <span class="mu">(aún no es el día)</span>';
const tot=x.sp+x.items.reduce((s,t)=>s+t.p*t.q,0);
return`<div class="mu">Total $${tot}</div><select id="cm${i}" style="width:auto"><option value="efectivo"${x.pay=="efectivo"?" selected":""}>Efectivo</option><option value="linea"${x.pay=="linea"?" selected":""}>Tarjeta</option></select><input id="ct${i}" type="number" min="0" placeholder="Propina" style="width:90px"><select id="cx${i}" style="width:auto"><option value="">+ Producto</option>${S.products.filter(p=>p.s>0).map(p=>`<option value="${p.id}">${esc(p.n)} $${pr(p)}</option>`).join("")}</select><button class="btn p" onclick="cobrarCita(${i})">Completar venta</button>`}
// ---- Inicio y diseño: logo, riel de imágenes, redes, mapa, promociones ----
const lk=(v,b)=>/^https?:/i.test(v)?v:b+v.replace(/^@/,"");
const railHome=()=>S.rail.length?`<div id="rail" style="display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;margin-bottom:14px">${S.rail.map(r=>`<div style="flex:0 0 85%;max-width:520px;scroll-snap-align:center;position:relative"><img src="${r.img}" style="width:100%;height:220px;object-fit:cover;border-radius:12px">${r.t?`<div style="position:absolute;left:0;right:0;bottom:0;padding:8px 12px;background:rgba(0,0,0,.55);color:#fff;border-radius:0 0 12px 12px">${esc(r.t)}</div>`:""}</div>`).join("")}</div>`:"";
let railT=0;
function startRail(){clearInterval(railT);if(!$("rail")||S.rail.length<2)return;railT=setInterval(()=>{const r=$("rail");if(!r){clearInterval(railT);return}const w=r.firstElementChild.offsetWidth+10;r.scrollTo({left:r.scrollLeft+w>=r.scrollWidth-5?0:r.scrollLeft+w,behavior:"smooth"})},3500)}
const promoHome=()=>{const t=ymd(new Date()),a=S.promos.filter(p=>p.from<=t&&p.to>=t),n=S.promos.filter(p=>p.from>t).sort((x,y)=>x.from.localeCompare(y.from));
return(a.length?`<div class="card"><h2>🎉 Promociones</h2>${a.map(p=>`<div><b>${esc(p.t)}</b> <span class="mu">hasta ${p.to}</span><br><span class="mu">${esc(p.d)}</span></div>`).join("")}</div>`:"")+(n.length?`<div class="card"><h2>Próximamente</h2>${n.map(p=>`<div><b>${esc(p.t)}</b> <span class="mu">desde ${p.from}</span><br><span class="mu">${esc(p.d)}</span></div>`).join("")}</div>`:"")};
const socHome=()=>{const s=S.shop,l=[["Instagram",s.ig&&lk(s.ig,"https://instagram.com/")],["Facebook",s.fb&&lk(s.fb,"https://facebook.com/")],["TikTok",s.tt&&lk(s.tt,"https://tiktok.com/@")],["YouTube",s.yt],["WhatsApp",s.wa&&"https://wa.me/"+s.wa]].filter(x=>x[1]);return l.length?`<div class="card hero" style="padding:12px"><h2>Síguenos</h2>${l.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener" class="btn" style="text-decoration:none;display:inline-block;margin:3px">${n}</a>`).join("")}</div>`:""};
const mapHome=()=>`<div class="card"><h2>📍 Ubicación</h2><p class="mu">${esc(S.shop.addr)}</p><iframe title="Mapa" loading="lazy" style="width:100%;height:260px;border:0;border-radius:10px" src="https://www.google.com/maps?q=${encodeURIComponent(S.shop.addr)}&output=embed"></iframe><br><a class="btn" style="text-decoration:none;display:inline-block;margin-top:8px" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(S.shop.addr)}">Cómo llegar</a></div>`;
const promoSt=p=>{const t=ymd(new Date());return p.to<t?"Vencida":p.from>t?"Programada":"Activa"};
function shp(k,v){S.shop[k]=v;save();toast("Guardado");if(k=="name"||k=="logo")render()}
async function setLogo(){const d=await rd($("lg").files[0],true,400);if(d){S.shop.logo=d;save();render()}}
async function addRail(){const d=await rd($("ri").files[0],false,900);if(!d)return toast("Elige una imagen");S.rail.push({id:Date.now(),img:d,t:$("rt2").value});save();render()}
function addPromo(){const t=$("pt").value.trim(),f=$("pf").value||ymd(new Date()),u=$("pu").value;if(!t||!u)return toast("Escribe título y fecha final");if(u<f)return toast("La fecha final es anterior al inicio");S.promos.push({id:Date.now(),t,d:$("pd").value,from:f,to:u});save();render()}
function tDesign(){const s=S.shop;
return`<div class="card"><h2>Logo y datos del negocio</h2><div class="grid"><div><label>Logo (imagen)</label><input id="lg" type="file" accept="image/*" onchange="setLogo()"></div><div><label>Nombre del negocio</label><input value="${esc(s.name)}" onchange="shp('name',this.value)"></div><div><label>Dirección del local</label><input value="${esc(s.addr)}" onchange="shp('addr',this.value)"></div></div>${s.logo?`<img src="${s.logo}" style="height:60px;margin-top:8px"> <button onclick="shp('logo','')">Quitar logo</button>`:""}<p class="mu">El mapa de Google del inicio usa esta dirección.</p></div>
<div class="card"><h2>Redes sociales</h2><div class="grid">${[["ig","Instagram (usuario o enlace)"],["fb","Facebook (usuario o enlace)"],["tt","TikTok (usuario o enlace)"],["yt","YouTube (enlace)"]].map(([k,l])=>`<div><label>${l}</label><input value="${esc(s[k]||"")}" onchange="shp('${k}',this.value.trim())"></div>`).join("")}</div><p class="mu">El WhatsApp se configura en Colores y datos.</p></div>
<div class="card"><h2>Imágenes del inicio (riel)</h2><div class="grid"><div><label>Imagen</label><input id="ri" type="file" accept="image/*"></div><div><label>Texto (opcional)</label><input id="rt2"></div></div><br><button class="btn p" onclick="addRail()">Agregar al riel</button><div class="row">${S.rail.map(r=>`<div class="card" style="width:140px"><img src="${r.img}" style="width:100%;border-radius:8px"><div class="mu">${esc(r.t)}</div><button onclick="S.rail=S.rail.filter(x=>x.id!=${r.id});save();render()">Quitar</button></div>`).join("")}</div></div>
<div class="card"><h2>Promociones (puedes programarlas por adelantado)</h2><div class="grid"><div><label>Título</label><input id="pt"></div><div><label>Descripción</label><input id="pd"></div><div><label>Desde</label><input id="pf" type="date"></div><div><label>Hasta</label><input id="pu" type="date"></div></div><br><button class="btn p" onclick="addPromo()">Agregar promoción</button>${S.promos.slice().sort((a,b)=>a.from.localeCompare(b.from)).map(p=>`<div class="row"><span style="flex:1"><b>${esc(p.t)}</b> · ${p.from} a ${p.to} · ${promoSt(p)}<br><span class="mu">${esc(p.d)}</span></span><button onclick="S.promos=S.promos.filter(x=>x.id!=${p.id});save();render()">Quitar</button></div>`).join("")||'<p class="mu">Sin promociones.</p>'}</div>`}
// ---- Perfil de empleado para el admin ----
function adminStaff(on){if(on){const id=Date.now();S.staff.push({id,n:S.me.name,st:S.staff.length+1,tel:"",bio:"",sv:[]});S.me.staffId=id}else{const id=S.me.staffId;S.staff=S.staff.filter(x=>x.id!=id);S.appts.forEach(x=>{if(x.staff==id)x.staff=0});S.me.staffId=0}save();render()}
function tMia(){const id=S.me.staffId,s=S.staff.find(x=>x.id==id);
if(!s)return`<div class="card"><h2>Mi perfil como empleado</h2><p class="mu">Actívalo si tú también atiendes citas. Aparecerás en la lista de empleados al agendar y tendrás tu propia agenda y cobro.</p><button class="btn p" onclick="adminStaff(1)">Yo también atiendo citas</button></div>`;
const l=S.appts.filter(x=>x.staff==id&&x.status!="cancelada");
return`<div class="card"><h2>Mi perfil como empleado</h2><div class="grid"><div><label>Estación #</label><input type="number" value="${s.st}" onchange="stf(${id},'st',this.value)"></div><div><label>Teléfono</label><input value="${esc(s.tel)}" onchange="stf(${id},'tel',this.value)"></div><div><label>Especialidad</label><input value="${esc(s.bio)}" onchange="stf(${id},'bio',this.value)"></div><div><label>Entrada (vacío = general)</label><input type="time" value="${s.so||""}" onchange="stf(${id},'so',this.value)"></div><div><label>Salida</label><input type="time" value="${s.sc||""}" onchange="stf(${id},'sc',this.value)"></div></div><details><summary>Servicios que realizo</summary>${svPanel(id,true)}</details><br><button onclick="adminStaff(0)">Dejar de atender citas</button></div>
<div class="card"><h2>Mi agenda</h2>${l.length?`<div class="scroll"><table><tr><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Productos</th><th>Cobro</th></tr>${l.map(x=>`<tr><td>${x.date} ${x.time}</td><td>${esc(x.client)}<div class="mu">${esc(whoTxt(x))}</div></td><td>${esc(x.service)}</td><td>${itemsTxt(x)}</td><td>${saleCell(x)}</td></tr>`).join("")}</table></div>`:'<p class="mu">Sin citas asignadas.</p>'}</div>`}
render();
